CREATE POLICY "service staff session access" ON public.staff_sessions TO service_role USING(auth.role()='service_role') WITH CHECK(auth.role()='service_role'); CREATE POLICY "service staff alert access" ON public.staff_alert_handling TO service_role USING(auth.role()='service_role') WITH CHECK(auth.role()='service_role'); CREATE INDEX staff_alert_assignee ON public.staff_alert_handling(assigned_to);